function band(n: number, step: number): string {
  const lo = Math.floor(n / step) * step;
  return `${lo.toLocaleString("ro-RO")} și ${(lo + step).toLocaleString("ro-RO")}`;
}

/** Indiciile calculate din date, valabile pentru orice județ. */
function derived(j: Judet): string[] {
  const letters = (s: string) => s.replace(/[^\p{L}]/gu, "");
  const out = [
    `Numele județului are ${letters(j.name).length} litere.`,
    `Numele începe cu litera „${j.name[0]}”.`,
    `Are între ${band(j.areaKm2, 1000)} km² (suprafață).`,
    `Are între ${band(j.population, 100000)} de locuitori.`,
    j.neighbors.length === 1
      ? "Se învecinează cu un singur județ."
      : `Se învecinează cu ${j.neighbors.length} județe.`,
    `Indicativul auto începe cu „${j.code[0]}”.`,
  ];
  if (j.seat) out.push(`Reședința are ${letters(j.seat).length} litere, iar numele ei începe cu „${j.seat[0]}”.`);
  return out;
}

/** Toate indiciile unui județ (scrise de mână + calculate). */
export function hintsFor(j: Judet): string[] {
  const hand = HAND[j.code] ?? [];
  return hand.length >= MAX_GUESSES - 1 ? [...hand] : [...hand, ...derived(j)];
}

function hashString(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

/**
 * Ordinea în care apar indiciile în ziua `date`: amestecată la întâmplare, dar stabilă
 * (același telefon sau alt dispozitiv vede aceleași indicii în aceeași zi). Prima e mereu
 * un indiciu scris de mână, ca să nu se înceapă cu unul calculat.
 */
export function hintOrder(date: string, target: Judet): string[] {
  let a = hashString(`${date}|${target.code}`);
  const rand = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const all = hintsFor(target);
  for (let i = all.length - 1; i > 0; i--) {
    const k = Math.floor(rand() * (i + 1));
    [all[i], all[k]] = [all[k], all[i]];
  }
  // Prima e un indiciu scris de mână (repere), nu unul calculat.
  const hand = HAND[target.code] ?? [];
  if (hand.length && !hand.includes(all[0])) {
    const k = all.findIndex((h) => hand.includes(h));
    [all[0], all[k]] = [all[k], all[0]];
  }
  return all.slice(0, MAX_GUESSES);
}
